import React from 'react';
import { BottomNavigation, BottomNavigationAction, Paper } from '@mui/material';
import { useNavigate, useLocation } from 'react-router-dom';
import HomeIcon from '@mui/icons-material/Home';
import TrendingUpIcon from '@mui/icons-material/TrendingUp';
import AttachMoneyIcon from '@mui/icons-material/AttachMoney';

const BottomNav = () => {
    const navigate = useNavigate();
    const location = useLocation();

    const getCurrentValue = () => {
        const path = location.pathname;
        if (path === '/' || path === '/Alumnos') return '/Alumnos';
        if (path === '/estadisticas') return '/estadisticas';
        if (path === '/VentaVarios') return '/VentaVarios';
        return path;
    };

    const [value, setValue] = React.useState(getCurrentValue());

    React.useEffect(() => {
        setValue(getCurrentValue());
    }, [location.pathname]);

    const handleChange = (event, newValue) => {
        setValue(newValue);
        navigate(newValue);
    };

    return (
        <Paper
            sx={{
                position: 'fixed',
                bottom: 20,
                left: '50%',
                transform: 'translateX(-50%)',
                width: 'auto',
                minWidth: 280,
                maxWidth: '90%',
                borderRadius: '50px',
                // Fondo más claro para que se vea el texto negro
                background: 'rgba(255, 255, 255, 0.25)',
                backdropFilter: 'blur(30px) saturate(200%)',
                WebkitBackdropFilter: 'blur(30px) saturate(200%)',
                border: '1px solid rgba(255, 255, 255, 0.3)',
                boxShadow: '0 8px 32px rgba(0, 0, 0, 0.12), inset 0 1px 0 rgba(255, 255, 255, 0.4)',
                zIndex: 1000,
                padding: '4px 8px',
                paddingBottom: 'calc(env(safe-area-inset-bottom) + 4px)',
                transition: 'all 0.3s ease',
            }}
            elevation={0}
        >
            <BottomNavigation
                value={value}
                onChange={handleChange}
                showLabels
                sx={{
                    backgroundColor: 'transparent',
                    height: 56,
                    '& .MuiBottomNavigationAction-root': {
                        color: 'rgba(0, 0, 0, 0.7)', // Negro semi-transparente
                        borderRadius: '40px',
                        transition: 'all 0.3s ease',
                        padding: '6px 12px',
                        '&:hover': {
                            backgroundColor: 'rgba(0, 0, 0, 0.05)',
                            color: 'rgba(0, 0, 0, 0.9)',
                        },
                        '&.Mui-selected': {
                            color: '#7c3aed', // Violeta cuando está seleccionado
                            backgroundColor: 'rgba(124, 58, 237, 0.15)',
                            backdropFilter: 'blur(10px)',
                            '& .MuiBottomNavigationAction-label': {
                                fontSize: '0.7rem',
                                fontWeight: 700,
                            },
                            '& .MuiSvgIcon-root': {
                                filter: 'drop-shadow(0 0 8px rgba(124, 58, 237, 0.3))',
                            }
                        }
                    },
                    '& .MuiBottomNavigationAction-label': {
                        color: 'rgba(0, 0, 0, 0.7)', // Negro semi-transparente
                        fontSize: '0.6rem',
                        fontWeight: 500,
                        transition: 'all 0.3s ease',
                        letterSpacing: '0.3px',
                    },
                    '& .MuiBottomNavigationAction-root.Mui-selected .MuiBottomNavigationAction-label': {
                        color: '#7c3aed', // Violeta cuando está seleccionado
                        fontSize: '0.7rem',
                        fontWeight: 700,
                    },
                    '& .MuiSvgIcon-root': {
                        fontSize: '1.5rem',
                        transition: 'all 0.3s ease',
                    }
                }}
            >
                <BottomNavigationAction
                    label="Inicio"
                    value="/Alumnos"
                    icon={<HomeIcon />}
                />
                <BottomNavigationAction
                    label="Estadísticas"
                    value="/estadisticas"
                    icon={<TrendingUpIcon />}
                />
                <BottomNavigationAction
                    label="Venta de Varios"
                    value="/VentaVarios"
                    icon={<AttachMoneyIcon />}
                />
            </BottomNavigation>
        </Paper>
    );
};

export default BottomNav;